import {day,uid,esc,keys,encrypt,decrypt,merge,nextDue,cycle,migrate,exportICS,importICS,occursOn} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const tabs=[['today','◉','Today','#b8a0ff'],['capture','✎','Capture','#eea6c9'],['plan','▦','Plan','#8dbaf6'],['tasks','☑','Tasks','#8dbaf6'],['projects','◇','Projects','#b8a0ff'],['routines','↻','Routines','#8fddbd'],['money','€','Budget','#edca89'],['journal','☷','Journal','#eea6c9'],['trackers','◷','Trackers','#8fddbd'],['analytics','▥','Insights','#8dbaf6'],['settings','⚙','Connect','#9299ac']];
const categories=['Business','Personal','Creative','Fun','Sports','Health','Admin','Rest'];
const colors=['#8dbaf6','#b8a0ff','#eea6c9','#edca89','#8fddbd','#a8d0aa','#d4b795','#a9acbd'];
let records={},base={},secret='',cryptoKeys,rev=0,busy=false,saveGeneration=0,activeEdit=null,editType=null,selected=day(),view=innerWidth<=600?'capture':'today',search='',filter='all',conflicts=[],lastSynced='',googleToken='',googleExpiry=0;
let editDefaults={},cacheId='',autoSyncTimer,typingTimer,toastTimer;
const all=type=>Object.values(records).filter(r=>!r.deleted&&(!type||r.type===type));
const cfg=()=>records.settings||{};
const categoryColor=c=>colors[Math.max(0,[...categories,...new Set(all().map(r=>r.category).filter(Boolean))].indexOf(c))%colors.length];
const tag=c=>`<span class="tag" style="--tag:${categoryColor(c)}">${esc(c||'Personal')}</span>`;
const money=n=>new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR'}).format(Number(n)||0);
const progress=(value,color='var(--accent)')=>`<div class="progress" style="--bar:${color}" role="progressbar" aria-label="Completion" aria-valuenow="${Math.round(Math.min(100,Math.max(0,value)))}" aria-valuemin="0" aria-valuemax="100"><i style="width:${Math.min(100,Math.max(0,value))}%"></i></div>`;
const duration=ms=>{const seconds=Math.max(0,Math.floor(ms/1000));return [Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(x=>String(x).padStart(2,'0')).join(':')};
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function status(text){$('#syncStatus').textContent=text}
function persist(){if(!cacheId)return;try{localStorage.setItem(cacheId,JSON.stringify({records,base,rev,conflicts}));}catch{status('Storage full · export now');toast('Device storage is full. Export a backup before closing.')}}
function put(r){records[r.id]={...r,updated:new Date().toISOString()};saveGeneration++;persist();status('Saved here · syncing…');clearTimeout(autoSyncTimer);autoSyncTimer=setTimeout(()=>sync(),700)}
function add(type,data){const id=uid();put({id,type,date:selected,...data});return id}
async function sync(){if(!secret||busy)return;busy=true;status('Syncing…');try{for(let attempt=0;attempt<4;attempt++){
 const headers={Authorization:'Bearer '+cryptoKeys.auth};let response=await fetch('/api/vault',{headers});if(!response.ok)throw Error('Cloud unavailable');const envelope=await response.json();const remote=envelope.data?await decrypt(envelope,cryptoKeys.key):{};
 const result=merge(base,records,remote);records=result.records;for(const c of result.conflicts)if(!conflicts.some(x=>x.id===c.id&&x.field===c.field&&JSON.stringify(x.remote)===JSON.stringify(c.remote)))conflicts.push(c);base=structuredClone(remote);rev=envelope.rev;
 if(JSON.stringify(records)===JSON.stringify(remote)){lastSynced=new Date().toLocaleTimeString('en-GB');status(conflicts.length?'Review sync conflicts':'Synced · '+lastSynced);persist();if(!document.activeElement.matches('input,textarea,select,[contenteditable]'))render();return}
 const snapshot=structuredClone(records),generation=saveGeneration;const encrypted=await encrypt(snapshot,cryptoKeys.key);response=await fetch('/api/vault',{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({...encrypted,rev})});if(response.status===409)continue;if(!response.ok)throw Error((await response.json()).error||'Sync failed');rev=(await response.json()).rev;base=snapshot;persist();lastSynced=new Date().toLocaleTimeString('en-GB');status(conflicts.length?'Review sync conflicts':'Synced · '+lastSynced);if(generation!==saveGeneration){setTimeout(sync,500)}if(!document.activeElement.matches('input,textarea,select,[contenteditable]'))render();return;
 }throw Error('Concurrent changes · retry shortly');}catch(e){persist();status('Offline / pending sync');toast(e.message+' · changes kept on this device')}finally{busy=false}}
async function unlock(key){if(!/^[A-Za-z0-9_-]{43}$/.test(key))throw Error('Use the full 43-character workspace key.');secret=key;cryptoKeys=await keys(secret);cacheId='life-v2-'+cryptoKeys.auth.slice(0,14);let local={};try{local=JSON.parse(localStorage.getItem(cacheId)||'{}')}catch{}records=local.records||{};base=local.base||{};rev=local.rev||0;conflicts=local.conflicts||[];
 if($('#rememberKey').checked)localStorage.setItem('life-workspace-key',secret);else sessionStorage.setItem('life-workspace-key',secret);
 const response=await fetch('/api/vault',{headers:{Authorization:'Bearer '+cryptoKeys.auth}}).catch(()=>null);if(response?.status===404){secret='';throw Error('Workspace not found. Use your private activation link or the key copied from a connected device.')}if(!response?.ok&&!Object.keys(records).length){secret='';throw Error('Cannot open this workspace while cloud storage is unavailable.')}$('#unlock').close();await sync();migrateDevice();render();}
function migrateDevice(){if(localStorage.getItem('life-migrated-'+cacheId))return;const old={};for(const [name,key]of [['tasks','matrixTasksV4'],['habits','matrixHabitsV4'],['roadmaps','matrixRoadmapsV4'],['dailyLogs','matrixDailyLogsV4']]){try{old[name]=JSON.parse(localStorage.getItem(key)||'null')}catch{}}if(Object.values(old).some(Boolean)){for(const r of Object.values(migrate(old))){if(records[r.id]){const existing=records[r.id];const fields=r.type==='task'?['title','notes','done','due','priority']:r.type==='routine'?['title','time']:r.type==='check'?['done']:[];const update={...existing};for(const f of fields){if(JSON.stringify(existing[f])!==JSON.stringify(r[f]))conflicts.push({id:r.id,field:f,local:r[f],remote:existing[f]});update[f]=r[f]}put(update)}else put(r)}toast('Your original device records have been merged.');}localStorage.setItem('life-migrated-'+cacheId,'1')}
function taskBlocked(t){return (t.deps||[]).some(id=>!records[id]?.done)||Number(t.availableBudget||0)<Number(t.cost||0)||(Number(t.availableMinutes||0)<Number(t.minutes||0)&&t.availableMinutes!==undefined&&t.availableMinutes!=='')}
function taskRow(t){const blocked=taskBlocked(t),due=t.due?`<span class="${t.due<day()?'overdue':'due'}">${esc(t.due)} ${esc(t.time||'')}</span>`:'';return `<div class="row ${t.done?'done':''}"><button class="check" data-action="complete" data-id="${esc(t.id)}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}">${t.done?'✓':blocked?'⌁':''}</button><div class="row-body"><button class="link-button" data-edit="${esc(t.id)}">${esc(t.title)}</button><small>${t.parent?'↳ '+esc(records[t.parent]?.title||'Parent task')+' · ':''}${t.milestone?'◆ milestone · ':''}${esc(t.category||'Personal')} · ${Number(t.minutes)||0}m ${t.cost?' · '+money(t.cost):''} ${due}${blocked?' · awaiting resources':''}${t.repeat&&t.repeat!=='none'?' · ↻ '+esc(t.repeat):''}</small></div><button data-action="start" data-id="${esc(t.id)}" aria-label="Track ${esc(t.title)}">▷</button></div>`}
function routineRow(r){const c=records['check-'+selected+'-'+r.id],done=c?.done;return `<div class="row ${done?'done':''}"><button class="check" data-action="check" data-id="${esc(r.id)}" aria-label="Log ${esc(r.title)}">${done?'✓':''}</button><div class="row-body"><button class="link-button" data-edit="${esc(r.id)}">${esc(r.title)}</button><small>${esc(r.time||'')} · ${esc(r.kind||'Routine')}${r.dose?' · '+esc(r.dose):''}</small></div>${tag(r.category||'Health')}</div>`}
const head=(title,action,label='+ Add')=>`<div class="card-head"><h2>${title}</h2>${action?`<button data-new="${action}">${label}</button>`:''}</div>`;
const empty=s=>`<div class="empty">${s}</div>`;
function dayStats(date){const routines=all('routine').filter(r=>!r.weekdays||r.weekdays.includes(new Date(date+'T12:00:00').getDay()));const tasks=all('task').filter(t=>t.due===date);const total=routines.length+tasks.length;const done=routines.filter(r=>records['check-'+date+'-'+r.id]?.done).length+tasks.filter(t=>t.done).length;return {total,done,pct:total?done/total*100:0}}
function sessions(date){return all('session').filter(s=>!date||s.date===date)}
function sessionMs(s){return Math.max(0,new Date(s.end||Date.now())-new Date(s.start))}
function statsHTML(){const stat=dayStats(selected),tasks=all('task'),focus=sessions(selected).reduce((a,s)=>a+sessionMs(s),0);return `<div class="stats"><div class="stat"><div class="eyebrow">TODAY'S MOMENTUM</div><div class="metric">${Math.round(stat.pct)}<small>%</small></div>${progress(stat.pct)}<small>${stat.done} of ${stat.total} planned actions</small></div><div class="stat"><div class="eyebrow">FOCUSED TIME</div><div class="metric">${(focus/3600000).toFixed(1)}<small> h</small></div><small>Time recorded on this date</small></div><div class="stat"><div class="eyebrow">OPEN LOOPS</div><div class="metric">${tasks.filter(t=>!t.done).length}</div><small>${tasks.filter(t=>!t.done&&t.due&&t.due<day()).length} past due · reschedule gently</small></div><div class="stat"><div class="eyebrow">PROGRESS</div><div class="metric">${tasks.filter(t=>t.done).length}<small> actions</small></div><small>Completed across your workspace</small></div></div>`}
function moodCard(){const entry=all('mood').filter(r=>r.date===selected).at(-1);return `${head('How are you, right now?')}<p class="muted">A signal to understand, without judgement.</p><div class="moods">${['Low','Heavy','Okay','Good','Great'].map((s,i)=>`<button data-mood="${i+1}" class="${entry?.value===i+1?'active':''}" aria-label="Mood ${s}">${['☁','◔','◑','◕','☀'][i]}</button>`).join('')}</div><label>Feeling or context<input id="feeling" placeholder="Calm, scattered, energised…" maxlength="250"></label><button data-action="feeling">Save feeling</button>${entry?`<p class="subtle">Latest: ${['Low','Heavy','Okay','Good','Great'][entry.value-1]||'Unrated'} ${esc(entry.feeling||'')}</p>`:''}`}
function captureView(){return `<div class="grid"><section class="card span8 focus-card">${head('Catch the thought.')}<label>Quick note<textarea id="quickNote" placeholder="An idea, something to remember, the next small step…"></textarea></label><div class="toolbar"><button class="primary" data-action="note">Save note</button><button data-new="task">Turn a thought into a task</button></div><p class="subtle">Capture now. Organise when you have space.</p></section><section class="card span4">${moodCard()}</section><section class="card span6">${timerCard()}</section><section class="card span6">${head('Recent notes','note')}${all('note').sort((a,b)=>(b.updated||'').localeCompare(a.updated||'')).slice(0,8).map(r=>`<div class="row"><div class="row-body"><button class="link-button" data-edit="${r.id}">${esc(r.title)}</button><small>${esc(r.date)} · ${esc(r.category||'Inbox')}</small></div><button data-action="noteTask" data-id="${r.id}">→ Task</button></div>`).join('')||empty('Your next idea has a home here.')}</section></div>`}
function todayView(){const focus=all('task').filter(t=>!t.done&&!taskBlocked(t)).sort((a,b)=>(b.focusDate===selected)-(a.focusDate===selected)||(a.due||'9999').localeCompare(b.due||'9999')||b.priority-a.priority).slice(0,3);const routines=all('routine').filter(r=>!r.weekdays||r.weekdays.includes(new Date(selected+'T12:00:00').getDay())).sort((a,b)=>(a.time||'').localeCompare(b.time||''));return statsHTML()+`<div class="grid"><section class="card span8 focus-card">${head('A little focus goes a long way.','task','+ Choose an action')}<p class="muted">Three next steps. Leave room for the rest of life.</p>${focus.map(taskRow).join('')||empty('No unblocked actions. Capture a task or review its dependencies.')}</section><section class="card span4">${moodCard()}</section><section class="card span6">${head('Your daily rhythm','routine')}${routines.map(routineRow).join('')||empty('Add an adjustable routine, medication or supplement slot.')}</section><section class="card span6">${head('Space for what matters','block')}${all('block').filter(r=>occursOn(r,selected)).sort((a,b)=>(a.time||'').localeCompare(b.time||'')).map(r=>`<div class="row"><span class="tag">${esc(r.time||'Anytime')}</span><div class="row-body"><button class="link-button" data-edit="${r.id}">${esc(r.title)}</button><small>${r.minutes||60} minutes · ${esc(r.category)}</small></div><button data-action="start" data-id="${r.id}">▷</button></div>`).join('')||empty('Protect time for creative work, sport, rest and fun.')}<div class="divider"></div>${head('Morning / evening check-in')}<div class="split"><button data-action="morning">☀ Morning · ${esc(cfg().morning||'04:00')}</button><button data-action="evening">☾ Evening · ${esc(cfg().evening||'23:00')}</button></div></section></div>`}
function tasksView(){let tasks=all('task').filter(t=>(t.title+' '+t.notes+' '+t.category).toLowerCase().includes(search.toLowerCase())).filter(t=>filter==='all'||filter==='open'&&!t.done||filter==='done'&&t.done||filter==='blocked'&&taskBlocked(t)||filter==='today'&&t.due===selected);tasks.sort((a,b)=>Number(a.done)-Number(b.done)||(a.due||'9999').localeCompare(b.due||'9999')||(b.priority||0)-(a.priority||0));return `<div class="toolbar"><input id="taskSearch" aria-label="Search tasks" placeholder="Search across your life…" value="${esc(search)}"><select id="taskFilter" aria-label="Task filter">${['all','open','today','blocked','done'].map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select><button class="primary" data-new="task">+ New task</button></div><section class="card">${head(tasks.length+' actions · one trusted place')}${tasks.map(taskRow).join('')||empty('Nothing here yet. Start with a small, specific action.')}</section>`}
function planView(){const current=new Date(selected+'T12:00:00'),start=new Date(current);start.setDate(current.getDate()-(current.getDay()+6)%7);const dates=Array.from({length:7},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return day(d)});return `<div class="toolbar"><button data-action="prevWeek">← Previous</button><button data-action="today">Today</button><button data-action="nextWeek">Next →</button><button class="primary" data-new="block">+ Time block</button><button data-new="task">+ Event / task</button></div><section class="card"><div class="week">${dates.map(date=>`<div class="day-column"><button data-date="${date}" ${date===selected?'class="primary"':''}>${new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short'})}</button>${all().filter(r=>(r.type==='task'&&r.due===date||r.type==='block'&&occursOn(r,date))).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99')).map(r=>`<div class="event" style="--tag:${categoryColor(r.category)}" role="button" tabindex="0" data-edit="${r.id}"><b>${esc(r.time||'Anytime')}</b><br>${esc(r.title)}<br><small>${r.minutes||30}m ${r.done?'✓':''}</small></div>`).join('')}${all('block').filter(r=>occursOn(r,date)).reduce((a,r)=>a+Number(r.minutes||0),0)>720?'<small class="due">Over 12h blocked — review capacity</small>':''}</div>`).join('')}</div></section><p class="subtle">All scheduling uses Europe/Vienna. Dragging is optional: tap any event to edit its date, time and category.</p>`}
function projectView(){return `<div class="toolbar"><button class="primary" data-new="project">+ New project</button><button data-new="goal">+ New goal</button><button data-new="task">+ Milestone / subtask</button></div><div class="grid">${all().filter(r=>['project','goal'].includes(r.type)).map(p=>{const tasks=all('task').filter(t=>t.project===p.id),pct=tasks.length?tasks.filter(t=>t.done).length/tasks.length*100:Number(p.progress||0);return `<section class="card span6 project">${head(esc(p.title))}<div class="toolbar">${tag(p.type)}<span class="tag">${esc(p.target||'Set a timeframe')}</span></div><p class="muted">${esc(p.notes||'Give this direction a clear next step.')}</p>${progress(pct)}<p class="subtle">${Math.round(pct)}% · ${tasks.filter(t=>t.done).length}/${tasks.length} actions · ${money(p.saved)} / ${money(p.budget)} funding</p>${tasks.slice(0,8).map(taskRow).join('')}<div class="toolbar"><button data-edit="${p.id}">Edit ${p.type}</button><button data-new="task" data-project="${p.id}">+ Action</button></div></section>`}).join('')||`<section class="card span12">${empty('Turn a direction into a project. Break it into milestones and small actions.')}</section>`}<section class="card span12">${head('See what unlocks what.')}<p class="muted">Select a node to edit its prerequisites. Connections update immediately; circular dependencies are rejected.</p>${dependencyGraph()}</section></div>`}
function dependencyGraph(){const ts=all('task').filter(t=>(t.deps||[]).length||all('task').some(x=>(x.deps||[]).includes(t.id))).slice(0,100);if(!ts.length)return empty('Add a prerequisite to a task to build your dependency map.');const levels={};function depth(t,seen=new Set()){if(seen.has(t.id))return 0;return Math.min(5,(t.deps||[]).reduce((max,id)=>Math.max(max,records[id]?1+depth(records[id],new Set([...seen,t.id])):0),0))}const pos={};for(const t of ts){const level=depth(t);levels[level]=(levels[level]||0)+1;pos[t.id]={x:level*250+15,y:(levels[level]-1)*90+15}}const width=(Math.max(...Object.keys(levels).map(Number))+1)*250,height=Math.max(...Object.values(levels))*90+25;return `<div class="graph"><svg viewBox="0 0 ${width} ${height}" aria-label="Interactive task dependency graph" role="img"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L0,6 L7,3 z" style="fill:#aaa;stroke:none"/></marker></defs>${ts.flatMap(t=>(t.deps||[]).filter(id=>pos[id]).map(id=>`<path marker-end="url(#arrow)" d="M${pos[id].x+210},${pos[id].y+25} C${pos[id].x+235},${pos[id].y+25} ${pos[t.id].x-25},${pos[t.id].y+25} ${pos[t.id].x},${pos[t.id].y+25}"/>`)).join('')}${ts.map(t=>`<g class="node" tabindex="0" role="button" aria-label="Edit ${esc(t.title)}" data-edit="${t.id}" transform="translate(${pos[t.id].x},${pos[t.id].y})"><rect width="210" height="55" rx="12" fill="${t.done?'#193c32':'#26243a'}" stroke="${taskBlocked(t)?'#edca89':'#b8a0ff'}"/><text x="12" y="23">${esc(t.title.slice(0,27))}</text><text x="12" y="42" style="font-size:10px;fill:#a9adbe">${t.done?'Complete':taskBlocked(t)?'Waiting on resources':'Ready to begin'}</text><title>${esc(t.title)}</title></g>`).join('')}</svg></div>${ts.length===100?'<p class="subtle">Showing the first 100 connected actions.</p>':''}`}
function routinesView(){return `<div class="grid"><section class="card span8">${head('A rhythm you can adjust.','routine')}<p class="muted">Choose days, times and reminders. Medication and supplement slots record your own instructions.</p>${all('routine').sort((a,b)=>(a.time||'').localeCompare(b.time||'')).map(routineRow).join('')}</section><section class="card span4">${head('Build consistency, gently.')}<p>Attach one small action to something you already do. Leave room for energy, recovery and change.</p><p class="muted">The completion tracker counts only routines scheduled for the selected day. Historical entries remain available when routines change.</p><button data-new="routine">+ Medication / supplement</button><div class="divider"></div><label>Morning check-in<input id="morningTime" type="time" value="${esc(cfg().morning||'04:00')}"></label><label>Evening check-in<input id="eveningTime" type="time" value="${esc(cfg().evening||'23:00')}"></label><button data-action="saveCheckin">Save check-in times</button></section></div>`}
function moneyView(){const month=selected.slice(0,7),entries=all('transaction').filter(t=>t.date?.startsWith(month)),income=entries.filter(t=>t.kind==='income').reduce((a,r)=>a+Number(r.amount),0),expense=entries.filter(t=>t.kind!=='income').reduce((a,r)=>a+Number(r.amount),0),limit=Number(cfg().budget||0);return `<div class="stats"><div class="stat"><div class="eyebrow">INCOME / ${month}</div><div class="metric">${money(income)}</div></div><div class="stat"><div class="eyebrow">SPENDING</div><div class="metric">${money(expense)}</div></div><div class="stat"><div class="eyebrow">NET CASH FLOW</div><div class="metric">${money(income-expense)}</div></div><div class="stat"><div class="eyebrow">BUDGET REMAINING</div><div class="metric">${limit?money(limit-expense):'—'}</div></div></div><div class="grid"><section class="card span8">${head('Every euro, with a purpose.','transaction')}${entries.sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<div class="row"><div class="row-body"><button class="link-button" data-edit="${r.id}">${esc(r.title)}</button><small>${esc(r.date)} · ${esc(r.category)} · ${esc(r.scope||'Personal')}</small></div><span style="color:${r.kind==='income'?'var(--green)':'var(--text)'}">${r.kind==='income'?'+':'−'} ${money(r.amount)}</span></div>`).join('')||empty('Add income and expenses. This is a planning ledger; reconcile it with your bookkeeping.')}</section><section class="card span4">${head('Monthly spending plan')}<label>Spending limit · EUR<input id="monthlyBudget" type="number" min="0" step="0.01" value="${limit}"></label><button data-action="budget">Save limit</button>${progress(limit?expense/limit*100:0,'var(--gold)')}<p class="subtle">${limit?Math.round(expense/limit*100)+'% used':'Set a limit to see progress.'}</p>${[...new Set(entries.filter(r=>r.kind!=='income').map(r=>r.category))].map(c=>{const n=entries.filter(r=>r.kind!=='income'&&r.category===c).reduce((a,r)=>a+Number(r.amount),0);return `<p>${tag(c)} ${money(n)}</p>`}).join('')}</section></div>`}
function journalView(){return `<div class="toolbar"><button class="primary" data-new="diary">+ Diary entry</button><button data-action="morning">Morning reflection</button><button data-action="evening">Evening reflection</button><button data-new="conscience">Values check-in</button></div><div class="grid"><section class="card span8">${head('A record of being human.')}<p class="muted">${selected} · Write to notice patterns, rather than judge a day.</p>${all().filter(r=>['diary','conscience'].includes(r.type)&&r.date===selected).map(r=>`<article class="row"><div class="row-body"><button class="link-button" data-edit="${r.id}">${esc(r.title||r.period||'Reflection')}</button><p class="notes-content">${esc(r.notes)}</p><small>${esc(r.type==='conscience'?'Values / conscience':r.period||'Diary')}${r.score?' · alignment '+r.score+'/5':''}</small></div></article>`).join('')||empty('What mattered today? What helped, and what would make tomorrow easier?')}</section><section class="card span4">${head('A moment of awareness')}<p>Values check-ins track whether your actions reflected your intentions. A lower score is information, never a verdict.</p><p class="muted">Morning: What is one meaningful action?<br>Evening: What worked? What do you need?<br>Conscience: Where did you act in line with your values? What can you repair?</p>${moodCard()}</section><section class="card span12">${head('Earlier entries')}<div class="list">${all().filter(r=>['diary','conscience'].includes(r.type)&&r.date!==selected).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30).map(r=>`<div class="row"><div class="row-body"><button class="link-button" data-edit="${r.id}">${esc(r.title||r.period||'Reflection')}</button><small>${esc(r.date)}</small></div><button data-date="${r.date}">View day</button></div>`).join('')}</div></section></div>`}
function timerCard(){const running=all('session').find(r=>!r.end);return head('Give this moment your attention.')+`<label>What are you doing?<input id="timerTitle" placeholder="Editing, bookkeeping, a bike ride…" value="${esc(running?.title||'')}"></label><div class="timer-big" data-timer-display>${duration(running?sessionMs(running):0)}</div><div class="toolbar">${running?'<button class="primary" data-action="stop">■ Stop & save</button>':'<button class="primary" data-action="timer">▷ Start timer</button>'}<button data-new="session">Add time manually</button></div><p class="subtle">Elapsed time uses timestamps and survives a reload. Stop the timer when finished.</p>`}
function trackersView(){return `<div class="toolbar"><button class="primary" data-new="tracker">+ New tracker</button></div><div class="grid"><section class="card span6">${timerCard()}</section><section class="card span6">${head('Recorded time')}${sessions(selected).map(r=>`<div class="row"><div class="row-body"><button class="link-button" data-edit="${r.id}">${esc(r.title)}</button><small>${esc(r.category||'Personal')} ${r.task?'· linked to action':''}</small></div>${duration(sessionMs(r))}</div>`).join('')||empty('Your focus sessions appear here.')}</section>${all('tracker').map(r=>{const logs=all('trackerLog').filter(l=>l.tracker===r.id).sort((a,b)=>(a.at||'').localeCompare(b.at||'')),last=logs.at(-1)?.at||r.since;const days=last?Math.floor((Date.now()-new Date(last))/86400000):null;return `<section class="card span4">${head(esc(r.title))}${tag(r.kind||'Time since')}<div class="metric" style="margin-top:18px">${days===null?'—':Math.max(0,days)} <small>days</small></div><p class="subtle">${last?'Since '+esc(new Date(last).toLocaleString('en-GB')):'Choose your own starting point'}</p><p class="muted">${r.kind==='Abstinence'?'Progress includes the choices you make today. A lapse does not erase the work you have done.':'Keep a helpful rhythm in sight.'}</p><div class="toolbar"><button data-action="trackerLog" data-id="${r.id}">${r.kind==='Abstinence'?'Record lapse':'Did this now'}</button><button data-edit="${r.id}">Adjust</button></div><small>${logs.length} recorded entries${r.targetDays?' · intention: '+r.targetDays+' days':''}</small>${logs.slice(-3).map(l=>`<p class="subtle">${esc(new Date(l.at).toLocaleString('en-GB'))} <button class="link-button" data-edit="${l.id}">Edit record</button></p>`).join('')}</section>`}).join('')}</div>`}
function analyticsView(){const days=Array.from({length:28},(_,i)=>{const dt=new Date(selected+'T12:00:00');dt.setDate(dt.getDate()-27+i);return day(dt)}),ms=all('mood').filter(r=>days.includes(r.date)&&r.value),avg=ms.length?ms.reduce((a,r)=>a+r.value,0)/ms.length:0,tx=all('transaction').filter(r=>days.includes(r.date)),spent=tx.filter(r=>r.kind!=='income').reduce((a,r)=>a+Number(r.amount),0),times=sessions().filter(r=>days.includes(r.date)),totalTime=times.reduce((a,r)=>a+sessionMs(r),0);const routineCounts=days.map(d=>dayStats(d));return `<div class="notice">Descriptive trends from your own entries over 28 days ending ${selected}. Missing days stay empty. Patterns do not establish causes or diagnose health conditions.</div>${statsHTML()}<div class="grid"><section class="card span6">${head('Consistency, in context.')}<div class="heatmap">${days.map(d=>{const s=dayStats(d);const has=all().some(r=>r.date===d&&['check','mood','diary','conscience','session'].includes(r.type));return `<button class="heat" data-date="${d}" title="${d}: ${s.done}/${s.total} actions" aria-label="${d}: ${s.done} of ${s.total}" style="padding:0;min-height:0;background:${has?'rgba(143,221,189,'+(0.15+s.pct/120)+')':'#ffffff0b'}"></button>`}).join('')}</div><p class="subtle">${routineCounts.reduce((a,r)=>a+r.done,0)} completed actions · ${days.filter(d=>all().some(r=>r.date===d)).length}/28 days with entries</p></section><section class="card span6">${head('Mood & reflection')}<div class="metric">${avg?avg.toFixed(1):'—'}<small> / 5 average mood</small></div><p class="subtle">${ms.length} mood observations</p>${[1,2,3,4,5].map(n=>{const count=ms.filter(r=>r.value===n).length;return `<div class="chart-row"><span>${['Low','Heavy','Okay','Good','Great'][n-1]}</span>${progress(ms.length?count/ms.length*100:0,'var(--pink)')}<span>${count}</span></div>`}).join('')}<p class="subtle">${all('diary').filter(r=>days.includes(r.date)).length} diary entries · ${all('conscience').filter(r=>days.includes(r.date)).length} values check-ins</p></section><section class="card span6">${head('Where your time went')}<div class="metric">${(totalTime/3600000).toFixed(1)}<small> hours tracked</small></div>${[...new Set(times.map(r=>r.category||'Personal'))].map(c=>{const n=times.filter(r=>(r.category||'Personal')===c).reduce((a,r)=>a+sessionMs(r),0);return `<div class="chart-row"><span>${esc(c)}</span>${progress(totalTime?n/totalTime*100:0,categoryColor(c))}<span>${(n/3600000).toFixed(1)}h</span></div>`}).join('')}</section><section class="card span6">${head('Money & capacity')}<div class="metric">${money(spent)}<small> spent / 28 days</small></div><p class="subtle">${money(tx.filter(r=>r.kind==='income').reduce((a,r)=>a+Number(r.amount),0))} income recorded</p><p>${all('task').filter(t=>taskBlocked(t)&&!t.done).length} actions waiting on resources</p><p>${(all('task').filter(t=>!t.done).reduce((a,r)=>a+Number(r.minutes||0),0)/60).toFixed(1)} hours of estimated backlog</p><p>${money(all('task').filter(t=>!t.done).reduce((a,r)=>a+Number(r.cost||0),0))} budget attached to open actions</p><p class="muted">Use estimates to choose what fits your week. Unscheduled work can stay in the backlog.</p></section><section class="card span12">${head('Progress by area')}${[...new Set(all('task').map(r=>r.category||'Personal'))].map(c=>{const ts=all('task').filter(t=>(t.category||'Personal')===c),done=ts.filter(t=>t.done).length;return `<div class="chart-row"><span>${esc(c)}</span>${progress(done/ts.length*100,categoryColor(c))}<span>${done}/${ts.length}</span></div>`}).join('')}</section></div>`}
function settingsView(){return `<div class="grid"><section class="card span6">${head('One workspace. Every device.')}<p class="muted">Open this same URL on your iPad, computer or phone, then enter the same workspace key. Sync runs on changes, when you return, and every 20 seconds while visible.</p><div class="toolbar"><button data-action="copyKey">Copy workspace key</button><button data-action="copyLink">Copy pairing link</button><button data-action="sync">Sync now</button><button data-action="lock">Lock this device</button></div><label class="inline"><input type="checkbox" id="keepConnected" ${localStorage.getItem('life-workspace-key')?'checked':''}> Keep this device connected</label><p class="subtle">The key grants access. Store it privately. Device caches contain readable records on this device; locking clears the current cache and saved key after syncing.</p><p class="subtle">Cloud revision ${rev} · ${lastSynced?'last synced '+lastSynced:'not synced yet'}</p><button data-action="history">View cloud save history</button><div id="historyOutput"></div></section><section class="card span6">${head('Portable backups')}<p class="muted">Export your complete workspace or exchange calendar and task files. JSON imports merge records; they never replace the whole workspace.</p><div class="toolbar"><button data-action="exportJSON">Export full JSON</button><button data-action="exportICS">Export calendar + tasks</button><button data-action="exportCSV">Export ledger CSV</button></div><label>Import planner JSON / Google Tasks JSON / .ics<input id="importFile" type="file" accept=".json,.ics,application/json,text/calendar"></label><p class="subtle">JSON and CSV downloads contain personal data. Calendar (.ics) exports include task due dates, scheduled blocks and reminder offsets. Import recurring occurrences from Google for calendar exceptions.</p></section><section class="card span12">${head('Google Calendar & Google Tasks')}<p class="muted">Explicit, on-demand sync. Preview the incoming records before importing; export planner records to Google without deleting remote items. Browser authorization is renewed when its access token expires.</p><label>Google OAuth web client ID<input id="googleClientId" placeholder="…apps.googleusercontent.com" value="${esc(cfg().googleClientId||'')}"></label><div class="toolbar"><button data-action="saveGoogle">Save client ID</button><button data-action="googleConnect">Connect Google</button><button data-action="googleDisconnect">Disconnect</button></div><p class="subtle" id="googleState">${googleToken&&Date.now()<googleExpiry?'Connected for this browser session':'Not connected. Create a Google OAuth web client with this site as an authorized JavaScript origin. Enable Calendar and Tasks APIs.'}</p><div class="split"><div><label>Calendar ID<input id="calendarId" value="${esc(cfg().calendarId||'primary')}"></label><button data-action="googleCalendars">List calendars</button><div id="calendarOutput"></div></div><div><label>Google task list ID<input id="tasklistId" value="${esc(cfg().tasklistId||'@default')}"></label><button data-action="googleTasklists">List task lists</button><div id="tasklistOutput"></div></div></div><label>Import / export window<input id="googleDays" type="number" min="1" max="365" value="90"></label><div class="toolbar"><button data-action="googlePreview">Preview Google import</button><button data-action="googlePush">Export to Google</button></div><p class="subtle">Google Calendar pop-up reminders use your 30m / 1h / 1d choice. Google Tasks exposes date-only due dates; timed reminders stay in Planner or Calendar. Re-import updates linked Google records. Planner export updates only its own previously exported records. This is manual exchange, not unattended two-way background sync.</p><div id="googlePreview"></div></section><section class="card span6">${head('Reminder preferences')}<button data-action="notifications">Enable browser notifications</button><p class="muted">Planner checks reminders while open. For reminders with the browser closed, export to Google Calendar. iPad notification availability depends on the browser and Home Screen installation.</p><label>Morning entry time<input id="morningTime" type="time" value="${esc(cfg().morning||'04:00')}"></label><label>Evening entry time<input id="eveningTime" type="time" value="${esc(cfg().evening||'23:00')}"></label><button data-action="saveCheckin">Save times</button></section><section class="card span6 ${conflicts.length?'conflict':''}">${head('Sync review')}<p class="muted">Different records and different fields merge automatically. If two devices change the same field, this device’s value is kept and the alternate value is retained here for review.</p>${conflicts.map((c,i)=>`<div class="row"><div class="row-body"><strong>${esc(records[c.id]?.title||c.id)} · ${esc(c.field)}</strong><pre>Alternate: ${esc(JSON.stringify(c.remote))}</pre><small>Current: ${esc(JSON.stringify(records[c.id]?.[c.field]))}</small><div class="toolbar"><button data-conflict="${i}" data-choice="remote">Use alternate</button><button data-conflict="${i}" data-choice="local">Keep current</button></div></div></div>`).join('')||empty('No conflicts to review.')}</section></div>`}
const renderers={today:todayView,capture:captureView,tasks:tasksView,plan:planView,projects:projectView,routines:routinesView,money:moneyView,journal:journalView,trackers:trackersView,analytics:analyticsView,settings:settingsView};
function render(){const t=tabs.find(t=>t[0]===view);$('#navigation').innerHTML=tabs.map(([id,icon,label,color])=>`<button data-view="${id}" class="${view===id?'active':''}" style="--tab:${color}" aria-current="${view===id?'page':'false'}"><span>${icon}</span>${label}</button>`).join('');$('#dateLabel').textContent=new Date(selected+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase();$('#selectedDay').value=selected;$('#viewTitle').textContent={today:'Today, with intention.',capture:'A place for every thought.',plan:'Make space for your life.',tasks:'From intention to action.',projects:'Build toward something.',routines:'Find your daily rhythm.',money:'Know where you stand.',journal:'Pause. Notice. Reflect.',trackers:'Notice your momentum.',analytics:'See the bigger picture.',settings:'Connected, on your terms.'}[view];$('#viewSubtitle').textContent={today:'Choose a little focus. Leave a little breathing room.',capture:'Quick notes, current feelings, and the time you spend.',projects:'Milestones, resources and the steps that unlock your next move.'}[view]||'';$('#content').innerHTML=renderers[view]();updateTimer()}
function field(name,label,type='text',value='',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(name,label,values,value){return `<label>${label}<select name="${name}">${values.map(v=>{const [id,title]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(title)}</option>`}).join('')}</select></label>`}
function textarea(name,label,value){return `<label class="full">${label}<textarea name="${name}">${esc(value||'')}</textarea></label>`}
function openEditor(type,id=null,defaults={}){const r=id?records[id]:{type,date:selected,...defaults};if(!r)return;activeEdit=id;editType=type;editDefaults=defaults;$('#editorTitle').textContent=(id?'Edit ':'New ')+({conscience:'values check-in',block:'time block',transaction:'ledger entry',diary:'diary entry',session:'time entry',routine:'routine / medication'}[type]||type);$('#deleteRecord').hidden=!id;const cats=[...new Set([...categories,...all().map(r=>r.category).filter(Boolean)])];let fields='';
 if(!['trackerLog'].includes(type))fields+=`<div class="full">${field('title','Title','text',r.title||'', 'required maxlength="250"')}</div>`;
 if(['task','block','note','routine','session','transaction'].includes(type))fields+=select('category','Area / category',cats,r.category||'Personal');
 if(['task','block'].includes(type)){
 fields+=field('due',type==='task'?'Due date':'Date','date',r.due||selected)+field('time',type==='task'?'Due time · optional':'Start time','time',r.time||'')+field('minutes','Estimated time · minutes','number',r.minutes??30,'min="1" max="1440"')+select('reminder','Reminder before',['none', ['30','30 minutes'],['60','1 hour'],['1440','1 day']],r.reminder||'none')+select('repeat','Repeat',['none','daily','weekly','monthly','yearly'],r.repeat||'none')+field('interval','Every N periods','number',r.interval||1,'min="1" max="365"');
 }
 if(type==='task'){
 fields+=field('priority','Importance · 1–10','number',r.priority||5,'min="1" max="10"')+field('focusDate','Focus on this date · optional','date',r.focusDate||'')+select('project','Project / goal',[['','No project'],...all().filter(r=>['project','goal'].includes(r.type)).map(p=>[p.id,p.title])],r.project||'')+select('parent','Parent task',[['','No parent'],...all('task').filter(t=>t.id!==id).map(t=>[t.id,t.title])],r.parent||'')+field('cost','Budget required · EUR','number',r.cost||0,'min="0" step="0.01"')+field('availableBudget','Budget allocated · EUR','number',r.availableBudget||0,'min="0" step="0.01"')+field('availableMinutes','Time available · minutes (blank = unrestricted)','number',r.availableMinutes??'','min="0"')+`<label class="inline"><input name="milestone" type="checkbox" ${r.milestone?'checked':''}> This is a milestone</label><label class="full">Prerequisite tasks · select all that must be completed<select name="deps" multiple size="6">${all('task').filter(t=>t.id!==id).map(t=>`<option value="${t.id}" ${(r.deps||[]).includes(t.id)?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label>`;
 }
 if(['project','goal'].includes(type))fields+=field('target','Target date','date',r.target||'')+field('budget','Budget needed · EUR','number',r.budget||0,'min="0" step="0.01"')+field('saved','Funding set aside · EUR','number',r.saved||0,'min="0" step="0.01"')+field('startDate','Start date','date',r.startDate||selected)+field('progress','Manual progress · % (when no linked tasks)','number',r.progress||0,'min="0" max="100"');
 if(type==='routine')fields+=select('kind','Type',['Routine','Medication','Supplement','Nutrition','Movement','Rest'],r.kind||'Routine')+field('time','Time','time',r.time||'08:00')+field('dose','Your instruction / dose · optional','text',r.dose||'')+select('reminder','Reminder before',[['none','None'],['30','30 minutes'],['60','1 hour'],['1440','1 day']],r.reminder||'none')+`<div class="full"><p class="muted">Repeat on these days</p><div class="toolbar">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label class="inline"><input type="checkbox" name="weekdays" value="${i}" ${!r.weekdays||r.weekdays.includes(i)?'checked':''}>${d}</label>`).join('')}</div></div>`;
 if(type==='transaction')fields+=select('kind','Direction',['expense','income'],r.kind||'expense')+field('amount','Amount · EUR','number',r.amount||0,'min="0.01" step="0.01" required')+field('date','Date','date',r.date||selected,'required')+select('scope','Scope',['Personal','Business'],r.scope||'Personal');
 if(['diary','conscience','note'].includes(type))fields+=field('date','Date','date',r.date||selected,'required');
 if(type==='diary')fields+=select('period','Entry',['Free writing','Morning','Evening'],r.period||'Free writing');
 if(type==='conscience')fields+=select('score','Actions aligned with my values · 1–5',[1,2,3,4,5],r.score||3);
 if(type==='session')fields+=field('start','Start · local device time','datetime-local',r.start?localDateTime(r.start):selected+'T09:00','required')+field('end','End · local device time','datetime-local',r.end?localDateTime(r.end):selected+'T09:30','required')+field('date','Reporting date','date',r.date||selected,'required');
 if(type==='tracker')fields+=select('kind','Type',['Time since','Abstinence'],r.kind||'Time since')+field('since','Starting point · optional','datetime-local',r.since?localDateTime(r.since):'')+field('targetDays','Intention · days','number',r.targetDays||0,'min="0"');
 if(type==='trackerLog')fields+=field('at','Event time','datetime-local',localDateTime(r.at),'required');
 fields+=textarea('notes',type==='conscience'?'What reflected your values? What would you change?':'Notes',r.notes);$('#editorFields').innerHTML='<div class="fields">'+fields+'</div>';$('#editor').showModal();setTimeout(()=>$('#editorFields input')?.focus(),30)}
function localDateTime(v){const d=new Date(v);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
$('#editForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),r={...(activeEdit?records[activeEdit]:editDefaults),id:activeEdit||uid(),type:editType};for(const [key,val]of fd.entries())if(!['deps','weekdays'].includes(key))r[key]=val;for(const key of ['minutes','interval','priority','cost','availableBudget','budget','saved','progress','amount','score','targetDays'])if(key in r)r[key]=Number(r[key]);if(r.availableMinutes!==undefined&&r.availableMinutes!=='')r.availableMinutes=Number(r.availableMinutes);if(r.reminder==='none')r.reminder='';if(editType==='task'){r.deps=fd.getAll('deps');r.milestone=fd.has('milestone');if(r.parent&&!r.deps.includes(r.parent)){/* parent groups work; it is not automatically a prerequisite */}if(cycle(records,r.id,r.deps)){toast('That dependency would create a circular chain.');return}let parent=r.parent;const visited=new Set([r.id]);while(parent){if(visited.has(parent)){toast('A task cannot be its own ancestor.');return}visited.add(parent);parent=records[parent]?.parent}}
 if(editType==='routine'){r.weekdays=fd.getAll('weekdays').map(Number);if(!r.weekdays.length){toast('Choose at least one routine day.');return}}
 if(editType==='session'){r.start=new Date(r.start).toISOString();r.end=new Date(r.end).toISOString();if(new Date(r.end)<=new Date(r.start)){toast('End time must be after start time.');return}}
 if(editType==='tracker'&&r.since)r.since=new Date(r.since).toISOString();if(editType==='trackerLog')r.at=new Date(r.at).toISOString();put(r);$('#editor').close();render();toast('Saved. Another small step forward.')};
$('#deleteRecord').onclick=()=>{if(activeEdit){put({...records[activeEdit],deleted:true});$('#editor').close();render();toast('Archived. Your cloud history retains earlier encrypted saves.')}};
function complete(id){const t=records[id];if(!t.done&&taskBlocked(t)){toast('This action needs its prerequisites, allocated budget or available time first.');openEditor('task',id);return}const done=!t.done;put({...t,done,completed:done?new Date().toISOString():null});if(done&&t.repeat&&t.repeat!=='none'){const next=nextDue(t.due||selected,t.repeat,t.interval||1),nid=t.id+'-next-'+next;if(!records[nid])put({...t,id:nid,due:next,done:false,completed:null,focusDate:'',googleId:null,googleSource:null,repeatParent:t.id})}render();if(done)toast('Completed. That counts.')}
function startTimer(t={}){const existing=all('session').find(r=>!r.end);if(existing){toast('Stop your current timer before starting another.');return}add('session',{title:t.title||$('#timerTitle')?.value.trim()||'Focus session',category:t.category||'Personal',task:t.id||'',date:day(),start:new Date().toISOString(),end:null});updateTimer();if(['trackers','capture'].includes(view))render()}
function stopTimer(){const r=all('session').find(r=>!r.end);if(r){put({...r,end:new Date().toISOString()});render();toast('Time saved.')}}
function updateTimer(){const running=all('session').find(r=>!r.end);$('#timerDock').hidden=!running;if(running){$('#timerDock').innerHTML=`<span>● ${esc(running.title)} · ${duration(sessionMs(running))}</span><button data-action="stop">■ Stop</button>`}$$('[data-timer-display]').forEach(el=>el.textContent=duration(running?sessionMs(running):0))}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied. Keep this private.')}catch{openEditor('note',null,{title:'Copy this workspace key',notes:text});toast('Clipboard unavailable. Select and copy the text.')}}
async function actions(action,id,el){switch(action){case 'complete':complete(id);break;case 'check':{const key='check-'+selected+'-'+id;put({id:key,type:'check',routine:id,date:selected,done:!records[key]?.done});render();break}case 'start':startTimer(records[id]);break;case 'timer':startTimer();break;case 'stop':stopTimer();break;case 'note':{const txt=$('#quickNote').value.trim();if(!txt)return;add('note',{title:txt.split('\n')[0].slice(0,100),notes:txt,category:'Inbox'});render();toast('Captured.');break}case 'noteTask':openEditor('task',null,{title:records[id].title,notes:records[id].notes});break;case 'feeling':{const feeling=$('#feeling').value.trim();if(feeling){add('mood',{feeling,value:0});render();toast('Feeling recorded.')}break}case 'morning':case 'evening':openEditor('diary',null,{title:action==='morning'?'Morning intention':'Evening reflection',period:action==='morning'?'Morning':'Evening',notes:action==='morning'?'What matters today?\n\nOne small next step:\n\nWhat support do I need?':'What went well?\n\nWhat felt difficult?\n\nWhat would help tomorrow?'});break;case 'budget':put({...cfg(),id:'settings',type:'settings',budget:Number($('#monthlyBudget').value)});render();break;case 'saveCheckin':put({...cfg(),id:'settings',type:'settings',morning:$('#morningTime').value,evening:$('#eveningTime').value});toast('Check-in times saved.');break;case 'trackerLog':openTrackerLog(id);break;case 'today':selected=day();render();break;case 'prevWeek':case 'nextWeek':{const d=new Date(selected+'T12:00:00');d.setDate(d.getDate()+(action==='nextWeek'?7:-7));selected=day(d);render();break}case 'lock':$('#lockButton').click();break;case 'copyKey':await copy(secret);break;case 'copyLink':await copy(location.origin+'/#vault='+secret);break;case 'sync':await sync();break;case 'history':{const r=await fetch('/api/history',{headers:{Authorization:'Bearer '+cryptoKeys.auth}});if(!r.ok)throw Error('History unavailable');$('#historyOutput').innerHTML=(await r.json()).map(x=>`<p class="subtle">Revision ${x.rev} · ${esc(x.updated)}</p>`).join('');break}case 'exportJSON':download('life-planner-'+day()+'.json',JSON.stringify({version:2,exported:new Date().toISOString(),records},null,2),'application/json');break;case 'exportICS':download('life-planner-'+day()+'.ics',exportICS(records),'text/calendar');break;case 'exportCSV':{const rows=[['Date','Title','Direction','Amount EUR','Category','Scope'],...all('transaction').map(r=>[r.date,r.title,r.kind,r.amount,r.category,r.scope])];download('planner-ledger-'+day()+'.csv',rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"').join(',')).join('\r\n'),'text/csv');break}case 'notifications':if('Notification'in window){const result=await Notification.requestPermission();toast('Notifications: '+result+'. Keep Planner open for its reminders.')}else toast('This browser does not support notifications.');break;
 case 'saveGoogle':put({...cfg(),id:'settings',type:'settings',googleClientId:$('#googleClientId').value.trim(),calendarId:$('#calendarId').value.trim(),tasklistId:$('#tasklistId').value.trim()});toast('Google configuration saved.');break;
 case 'googleConnect':await googleConnect();break;case 'googleDisconnect':if(window.google&&googleToken)google.accounts.oauth2.revoke(googleToken);googleToken='';googleExpiry=0;render();break;case 'googleCalendars':await googleList('calendars');break;case 'googleTasklists':await googleList('tasks');break;case 'googlePreview':await previewGoogle();break;case 'googleApply':for(const r of googleIncoming)put(r);toast(googleIncoming.length+' Google records imported.');googleIncoming=[];render();break;case 'googlePush':await pushGoogle();break;
 }}
function openTrackerLog(id){const tracker=records[id];openEditor('trackerLog',null,{tracker:id,at:new Date().toISOString(),notes:tracker.kind==='Abstinence'?'Optional context: what happened, and what support would help next?':''});}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-edit],[data-date]');if(!el)return;try{if(el.dataset.view){view=el.dataset.view;render();window.scrollTo(0,0)}if(el.dataset.new)openEditor(el.dataset.new,null,{project:el.dataset.project||''});if(el.dataset.edit){const r=records[el.dataset.edit];openEditor(r.type,r.id)}if(el.dataset.close!==undefined)$('#editor').close();if(el.dataset.date){selected=el.dataset.date;view='today';render()}if(el.dataset.mood){add('mood',{value:Number(el.dataset.mood),feeling:$('#feeling')?.value||''});render();toast('Mood recorded.')}if(el.dataset.action)await actions(el.dataset.action,el.dataset.id,el);if(el.dataset.conflict){const i=Number(el.dataset.conflict),c=conflicts[i];if(el.dataset.choice==='remote')put({...records[c.id],[c.field]:c.remote});conflicts.splice(i,1);persist();render()}}catch(err){toast(err.message)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-edit]:not(button)')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('change',e=>{if(e.target.id==='selectedDay'){selected=e.target.value||day();render()}if(e.target.id==='taskFilter'){filter=e.target.value;render()}if(e.target.id==='importFile')importFile(e.target.files[0]);if(e.target.id==='keepConnected'){if(e.target.checked)localStorage.setItem('life-workspace-key',secret);else localStorage.removeItem('life-workspace-key')}});
document.addEventListener('input',e=>{if(e.target.id==='taskSearch'){search=e.target.value;clearTimeout(typingTimer);typingTimer=setTimeout(()=>{const pos=e.target.selectionStart;render();$('#taskSearch').focus();$('#taskSearch').setSelectionRange(pos,pos)},250)}});
$('#quickAdd').onclick=()=>openEditor(innerWidth<=600?'note':'task');$('#syncButton').onclick=sync;
$('#lockButton').onclick=async()=>{await sync();if(JSON.stringify(records)!==JSON.stringify(base)){toast('Cloud sync is pending. Export a backup or reconnect before locking.');return}localStorage.removeItem(cacheId);localStorage.removeItem('life-workspace-key');sessionStorage.removeItem('life-workspace-key');location.reload()};
$('#unlockForm').onsubmit=async e=>{e.preventDefault();$('#unlockError').textContent='';try{await unlock($('#workspaceKey').value.trim())}catch(err){$('#unlockError').textContent=err.message}};

async function importFile(file){if(!file)return;try{const text=await file.text();let incoming;if(file.name.endsWith('.ics'))incoming=importICS(text);else{const data=JSON.parse(text);if(data.records)incoming=data.records;else if(data.tasks||data.habits)incoming=migrate(data);else if(data.items||Array.isArray(data)){incoming={};for(const t of data.items||data){const id='google-task-'+(t.id||uid());incoming[id]={id,type:'task',title:t.title||t.name||'Imported task',notes:t.notes||'',due:(t.due||'').slice(0,10),done:t.status==='completed',category:'Imported',deps:[],repeat:'none',minutes:30,cost:0,priority:5}}}else throw Error('Unsupported file format')}
 const entries=Object.values(incoming);if(!entries.length)throw Error('No records found');if(entries.some(r=>!r||typeof r.id!=='string'||['__proto__','constructor','prototype'].includes(r.id)||!/^[\w@.\-: /+%=]+$/.test(r.id)||!['task','routine','project','goal','check','block','note','mood','transaction','diary','conscience','session','tracker','trackerLog','settings'].includes(r.type)))throw Error('Invalid planner records');pendingImport=entries;$('#editorTitle').textContent='Review import';activeEdit=null;$('#deleteRecord').hidden=true;$('#editorFields').innerHTML=`<p>${entries.length} records ready. Existing records with matching IDs will be updated. Export a backup first if you want to preserve their current values.</p><p>${entries.slice(0,10).map(r=>esc(r.title||r.type)).join('<br>')}</p><button type="button" data-action="applyImport">Import these records</button>`;$('#editor .dialog-actions').hidden=true;$('#editor').showModal();}catch(e){toast(e.message)}}
let pendingImport=[];document.addEventListener('click',e=>{if(e.target.dataset.action==='applyImport'){for(const r of pendingImport)put(r);pendingImport=[];$('#editor').close();render();toast('Import complete.')}});$('#editor').addEventListener('close',()=>$('#editor .dialog-actions').hidden=false);
function reminderCheck(){if(!secret)return;const now=new Date(),date=day(now),tomorrow=day(new Date(now.getTime()+86400000)),targets=[...all('task').filter(t=>!t.done&&t.due&&t.time&&t.reminder),...[date,tomorrow].flatMap(d=>all('block').filter(t=>t.time&&t.reminder&&occursOn(t,d)).map(t=>({...t,due:d}))),...[date,tomorrow].flatMap(d=>all('routine').filter(r=>r.reminder&&(!r.weekdays||r.weekdays.includes(new Date(d+'T12:00:00').getDay()))).map(r=>({...r,due:d}))),{id:'morning-checkin',title:'Morning intention',due:date,time:cfg().morning||'04:00',reminder:0},{id:'evening-checkin',title:'Evening reflection',due:date,time:cfg().evening||'23:00',reminder:0}];for(const t of targets){const at=viennaInstant(t.due,t.time)-Number(t.reminder||0)*60000,diff=now-at,key='reminder-'+t.id+'-'+t.due+'-'+t.time+'-'+t.reminder;if(diff>=0&&diff<90000&&!sessionStorage.getItem(key)){sessionStorage.setItem(key,'1');toast('Reminder: '+t.title);if('Notification'in window&&Notification.permission==='granted'){try{new Notification('Life Planner',{body:t.title,tag:key})}catch{}}}}}
function viennaInstant(date,time){const raw=new Date(date+'T'+time+':00Z');const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Vienna',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(raw);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));const displayed=Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:00Z`);return raw.getTime()-(displayed-raw.getTime())}
let googleIncoming=[];
async function googleConnect(){const clientId=cfg().googleClientId;if(!clientId)throw Error('Save a Google OAuth web client ID first.');if(!window.google)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.onload=resolve;s.onerror=()=>reject(Error('Could not load Google sign-in'));document.head.appendChild(s)});return new Promise((resolve,reject)=>{google.accounts.oauth2.initTokenClient({client_id:clientId,scope:'https://www.googleapis.com/auth/calendar.events https://www.googleapis.com/auth/calendar.calendarlist.readonly https://www.googleapis.com/auth/tasks',callback:r=>{if(r.error){reject(Error(r.error));return}googleToken=r.access_token;googleExpiry=Date.now()+Number(r.expires_in)*1000;render();toast('Google connected for this session.');resolve()},error_callback:()=>reject(Error('Google authorization was cancelled or blocked'))}).requestAccessToken({prompt:'consent'})})}
async function gfetch(path,options={}){if(!googleToken||Date.now()>=googleExpiry)throw Error('Connect Google first (or renew the session).');const res=await fetch('https://www.googleapis.com/'+path,{...options,headers:{Authorization:'Bearer '+googleToken,'Content-Type':'application/json'}});if(!res.ok){const err=await res.json().catch(()=>({}));throw Error(err.error?.message||'Google request failed: '+res.status)}return res.status===204?{}:res.json()}
async function googleList(kind){const data=await gfetch(kind==='calendars'?'calendar/v3/users/me/calendarList':'tasks/v1/users/@me/lists');const output=kind==='calendars'?'#calendarOutput':'#tasklistOutput';$(output).innerHTML=(data.items||[]).map(x=>`<p class="subtle">${esc(x.summary||x.title)}<br>${esc(x.id)}</p>`).join('')}
async function listPages(path){let items=[],pageToken;do{const data=await gfetch(path+(pageToken?'&pageToken='+encodeURIComponent(pageToken):''));items.push(...(data.items||[]));pageToken=data.nextPageToken;if(items.length>10000)throw Error('Too many Google records. Use a smaller import window.')}while(pageToken);return items}
async function previewGoogle(){const calendar=$('#calendarId').value.trim()||'primary',tasklist=$('#tasklistId').value.trim()||'@default',days=Math.min(365,Math.max(1,Number($('#googleDays').value))),min=new Date(selected+'T00:00:00Z').toISOString(),max=new Date(new Date(min).getTime()+days*86400000).toISOString();const [events,tasks]=await Promise.all([listPages(`calendar/v3/calendars/${encodeURIComponent(calendar)}/events?singleEvents=true&maxResults=250&timeMin=${encodeURIComponent(min)}&timeMax=${encodeURIComponent(max)}`),listPages(`tasks/v1/lists/${encodeURIComponent(tasklist)}/tasks?maxResults=100&showCompleted=true&showHidden=true`)]);googleIncoming=[];for(const e of events.filter(e=>e.status!=='cancelled')){const existing=all('block').find(r=>r.googleId===e.id&&r.googleCalendar===calendar),start=e.start.dateTime?new Date(e.start.dateTime):null,id=existing?.id||uid();googleIncoming.push({...existing,id,type:'block',title:e.summary||'Untitled Google event',notes:e.description||'',due:start?day(start):e.start.date,time:start?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Vienna',hour:'2-digit',minute:'2-digit'}).format(start):'',minutes:start?Math.max(1,(new Date(e.end.dateTime)-start)/60000):60,category:existing?.category||'Imported',googleId:e.id,googleCalendar:calendar,googleSource:'calendar',googleUpdated:e.updated})}for(const t of tasks.filter(t=>!t.deleted)){const existing=all('task').find(r=>r.googleId===t.id&&r.googleTasklist===tasklist);googleIncoming.push({...existing,id:existing?.id||uid(),type:'task',title:t.title||'Untitled Google task',notes:t.notes||'',due:(t.due||'').slice(0,10),done:t.status==='completed',minutes:existing?.minutes||30,cost:existing?.cost||0,category:existing?.category||'Imported',priority:existing?.priority||5,deps:existing?.deps||[],repeat:existing?.repeat||'none',googleId:t.id,googleTasklist:tasklist,googleSource:'tasks',googleUpdated:t.updated})}$('#googlePreview').innerHTML=`<div class="notice">${googleIncoming.length} records will be imported or updated. Matching linked records use Google values for title, notes, due date and completion. Review local edits before continuing. Tasks are fetched from the entire selected list; events use the date window.</div>${googleIncoming.slice(0,15).map(r=>`<p>${tag(r.type)} ${esc(r.title)} · ${esc(r.due||'No date')}</p>`).join('')}<button data-action="googleApply" class="primary">Import ${googleIncoming.length} records</button>`}
async function pushGoogle(){const calendar=$('#calendarId').value.trim()||'primary',tasklist=$('#tasklistId').value.trim()||'@default',days=Math.min(365,Math.max(1,Number($('#googleDays').value))),end=new Date(new Date(selected+'T12:00:00').getTime()+days*86400000);const candidates=all().filter(r=>['task','block'].includes(r.type)&&(!r.due||r.due>=selected&&r.due<=day(end)));let count=0;for(const r of candidates){if(r.repeatParent)continue;let path,body;if(r.type==='block'){if(!r.due)continue;path=`calendar/v3/calendars/${encodeURIComponent(calendar)}/events`;const dateTime=new Date(viennaInstant(r.due,r.time||'09:00')).toISOString();body={summary:r.title,description:r.notes||'',start:{dateTime,timeZone:'Europe/Vienna'},end:{dateTime:new Date(Date.parse(dateTime)+Number(r.minutes||60)*60000).toISOString(),timeZone:'Europe/Vienna'},reminders:r.reminder?{useDefault:false,overrides:[{method:'popup',minutes:Number(r.reminder)}]}:{useDefault:true}};if(r.repeat&&r.repeat!=='none')body.recurrence=[`RRULE:FREQ=${r.repeat.toUpperCase()};INTERVAL=${r.interval||1}`]}else{path=`tasks/v1/lists/${encodeURIComponent(tasklist)}/tasks`;body={title:r.title,notes:r.notes||'',status:r.done?'completed':'needsAction'};body.due=r.due?r.due+'T00:00:00.000Z':null}
 const match=r.googleExported&&r.googleId&&((r.type==='block'&&r.googleCalendar===calendar)||(r.type==='task'&&r.googleTasklist===tasklist));const result=await gfetch(path+(match?'/'+encodeURIComponent(r.googleId):''),{method:match?'PATCH':'POST',body:JSON.stringify(body)});put({...r,googleId:result.id,googleCalendar:r.type==='block'?calendar:undefined,googleTasklist:r.type==='task'?tasklist:undefined,googleExported:true,googleUpdated:result.updated});count++}toast(count+' records exported to Google.');render()}
setInterval(()=>{updateTimer();reminderCheck()},1000);setInterval(()=>{if(!document.hidden&&secret)sync()},20000);window.addEventListener('online',sync);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&secret){sync();reminderCheck()}});window.addEventListener('beforeunload',()=>persist());
render();$('#unlock').showModal();const fragment=new URLSearchParams(location.hash.slice(1)).get('vault');if(fragment)history.replaceState(null,'',location.pathname);const saved=fragment||localStorage.getItem('life-workspace-key')||sessionStorage.getItem('life-workspace-key');if(saved){$('#rememberKey').checked=!!localStorage.getItem('life-workspace-key');unlock(saved).catch(e=>$('#unlockError').textContent=e.message)}
